const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coupons=[['甜點兌換券','🍰','美味補給','挑一份喜歡的甜點，今天的甜度由我負責。'],['飲料兌換券','🧋','美味補給','你的專屬外送員上線，甜度冰塊都記得。'],['宵夜兌換券','🍜','美味補給','晚一點也沒關係，陪你把肚子和心填滿。'],['早餐兌換券','🥐','美味補給','把早安做成你最喜歡的早餐。'],['大餐兌換券','🍝','美味補給','今晚你選餐廳，我負責買單與陪伴。'],['抱抱充電券','🧸','親密時光','給你一個不趕時間、剛剛好的擁抱。'],['親親兌換券','💋','親密時光','在彼此都願意的時候，送上一個甜甜的吻。'],['按摩放鬆券','👐','親密時光','舒舒服服的肩頸按摩，力道由你決定。'],['撒嬌通行券','🎀','親密時光','今天可以多黏我一點，你的撒嬌我接住。'],['浪漫約會券','🌷','一起生活','留一個下午給我們，行程由我用心安排。'],['電影之夜券','🎬','一起生活','你選電影，我準備零食與最舒服的位置。'],['散步牽手券','🌙','一起生活','把手機收起來，陪你慢慢走一段路。'],['家事代勞券','🧺','貼心照顧','挑一件家事交給我，讓你安心休息。'],['專心聽你說券','💌','貼心照顧','不急著給建議，先好好聽你把話說完。'],['驚喜小禮券','🎁','貼心照顧','一份為你挑選、在約定預算內的小驚喜。'],['任性願望券','✨','貼心照顧','提出一個小願望，我們一起商量怎麼完成。']].map((a,i)=>({id:i,name:a[0],icon:a[1],category:a[2],desc:a[3]}));
const pages=[['home','⌂','補給站首頁'],['shop','✂','戀愛兌換券'],['draw','☆','每週小幸運'],['letters','✉','悄悄情書'],['wishes','✧','許願池'],['mood','☀','今天的心情'],['memories','▧','我們的回憶'],['games','⚄','情侶小遊戲'],['admin','⚙','男友後台']];
const KEY='love-station-v1';const uid=()=>crypto.randomUUID();
const initial=()=>({wallet:[{id:uid(),coupon:0,status:'available',source:'體驗贈券'},{id:uid(),coupon:1,status:'available',source:'體驗贈券'},{id:uid(),coupon:5,status:'available',source:'體驗贈券'}],draws:[],letters:[{id:'sample-letter',title:'給今天也很可愛的你',body:'不用每天都很厲害，也不用一直開心。\n在我這裡，你可以放心做你自己。\n\n累的時候就來補給一下吧，抱抱和甜點都幫你留好了。',from:'帥氣可愛小寶貝男友',date:'展示情書',sample:true}],wishes:[],moods:[],memories:[],settings:{name:'寶貝',anniversary:''}});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}let page='home',filter='全部',shopMode='catalog',moodSelected='開心',gameType='真心話',busy=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('儲存空間不足，請移除較大的回憶照片後重試。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
const date=()=>new Date().toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
function weekInfo(now=Date.now()){const d=new Date(now+8*3600000);const day=d.getUTCDay();d.setUTCDate(d.getUTCDate()-((day+6)%7));d.setUTCHours(0,0,0,0);return {key:d.toISOString().slice(0,10),next:d.getTime()-8*3600000+7*86400000}}
// Replace with an authenticated backend adapter. The server MUST select the prize and
// atomically enforce UNIQUE(couple_id, user_id, week_start) in Asia/Taipei.
// GET /api/weekly-draw => {eligible,nextDrawAt}; POST /api/weekly-draw
// with Idempotency-Key => {couponId,issuedCouponId,weekStart,nextDrawAt}; 409 if already drawn.
window.loveApi={mode:'demo',async getWeeklyStatus(){const w=weekInfo();return {eligible:!state.draws.some(d=>d.week===w.key),nextDrawAt:w.next}},async drawWeekly(){const run=async()=>{try{state=JSON.parse(localStorage.getItem(KEY))||state}catch{}const w=weekInfo();if(state.draws.some(d=>d.week===w.key))throw Error('本週已領過幸運券囉，下週一再來！');const n=new Uint32Array(1);crypto.getRandomValues(n);const couponId=Math.floor(n[0]/4294967296*coupons.length);const record={id:uid(),coupon:couponId,status:'available',source:'每週抽獎'};state.wallet.push(record);state.draws.push({week:w.key,coupon:couponId,date:date()});if(!save()){state.wallet.pop();state.draws.pop();throw Error('無法儲存抽獎結果，請先確認本機儲存空間。')}return {couponId,issuedCouponId:record.id,weekStart:w.key,nextDrawAt:w.next}};return navigator.locks? navigator.locks.request('love-weekly-draw',run):run()}};
let installEvt=null;const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;const isIOS=/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
function installCard(){if(standalone())return '';if(installEvt)return `<div class="banner row between"><span>把補給站放到手機桌面，打開就像 App ♡</span><button id="installApp" class="primary">加到桌面</button></div>`;if(isIOS)return '<div class="banner">♡ 想放到手機桌面嗎？用 Safari 點下方「分享」，再選「加入主畫面」。</div>';return ''}
function pageHeading(k,title,desc){return `<div class="page-top"><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>`}
function formKey(f){return f.id||f.dataset.id}
function keepForms(){const a=document.activeElement;return {focus:a?.form&&$('#app').contains(a)?[formKey(a.form),a.name]:null,forms:[...document.querySelectorAll('#app form')].map(f=>[formKey(f),[...f.elements].filter(x=>x.name&&x.type!=='file').map(x=>[x.name,x.value])])}}
function restoreForms(k){for(const [key,vals] of k.forms){const f=[...document.querySelectorAll('#app form')].find(f=>formKey(f)===key);if(f)for(const [n,v] of vals)if(f.elements[n])f.elements[n].value=v}if(k.focus){const f=[...document.querySelectorAll('#app form')].find(f=>formKey(f)===k.focus[0]);f?.elements[k.focus[1]]?.focus()}}
function render(keep){const kept=keep?keepForms():null;page=location.hash.slice(1)||'home';if(!pages.some(x=>x[0]===page))page='home';$('#nav').innerHTML=pages.map(x=>`<a href="#${x[0]}" class="${page===x[0]?'active':''}" ${page===x[0]?'aria-current="page"':''}><span>${x[1]}</span>${x[2]}</a>`).join('');$('#walletCount').textContent=state.wallet.filter(x=>x.status==='available').length;$('#app').innerHTML=({home,shop,draw,letters,wishes,mood,memories,games,admin})[page]();if(kept)restoreForms(kept);updateCountdown()}
function home(){const days=state.settings.anniversary?Math.max(0,Math.floor((Date.now()-new Date(state.settings.anniversary+'T00:00:00+08:00'))/86400000)+1):null;return `<section class="hero"><div><div class="eyebrow">A LITTLE LOVE, JUST FOR YOU</div><h1>嗨，${esc(state.settings.name)}。<br>今天也要被寵愛 ♡</h1><p>把小小的喜歡，變成摸得到的幸福。<br>這裡的甜、抱抱和偏愛，通通只給你。</p><button class="primary" data-page="shop">領取今天的甜蜜 ↗</button></div><img src="assets/dessert.webp" alt="粉紅手繪甜點兌換券：奶油白小狗、蝴蝶結灰貓與草莓蛋糕"></section>${installCard()}<div class="section-head"><div><h2>今天，想補給什麼？</h2><p>不需要特別的理由，你值得一點小幸福。</p></div><span class="eyebrow">LOVE MENU</span></div><div class="grid quick-grid"><button class="card quick-card" data-page="shop"><span class="icon">🎟️</span><h3>把喜歡兌現</h3><p>甜點、約會、抱抱，16 種偏愛 →</p></button><button class="card quick-card" data-page="draw"><span class="icon">🎁</span><h3>每週的小幸運</h3><p>${state.draws.some(d=>d.week===weekInfo().key)?'本週驚喜已收到，下週再見':'本週還有 1 次，來拆開驚喜'} →</p></button><button class="card quick-card" data-page="letters"><span class="icon">💌</span><h3>有些話，只想給你</h3><p>打開一封藏著喜歡的情書 →</p></button></div><div class="home-bottom"><div class="note"><div class="eyebrow">A NOTE FOR YOU</div><h2 style="margin-top:13px">今天也辛苦了。</h2><p>世界可以很忙，但我會記得，<br>把最柔軟的位置留給你。</p><div class="small" style="text-align:right;margin-top:13px">— 你的專屬補給員 ♡</div></div><div class="card"><div class="row between"><h3>我們的小日常</h3><span class="tag">${days?`相愛第 ${days} 天`:'等待填上紀念日'}</span></div><p>今天的心情，有沒有想偷偷告訴我？</p><div class="moods">${[['🥰','開心'],['🙂','平靜'],['🥺','低落'],['😴','疲累']].map(([x,t])=>`<button data-page="mood" data-mood="${t}" aria-label="記錄今天的心情：${t}">${x}</button>`).join('')}</div><button class="text-link" data-page="memories">收藏一個屬於我們的瞬間 ↗</button></div></div>`}
function ticket(c,w){return `<article class="ticket"><div class="ticket-art">${c.id===0?'<img src="assets/dessert.webp" alt="原版甜點券">':`<span>${c.icon}</span>`}</div><div class="ticket-body"><span class="small">${c.category} · ${w?esc(w.source):'LOVE COUPON '+String(c.id+1).padStart(2,'0')}</span><h3>${c.name}</h3><p>${c.desc}</p>${w?`<button ${w.status!=='available'?'disabled':''} data-redeem="${w.id}">${({available:'使用這張券 ♡',pending:'等待男友回應',done:'已完成兌換'})[w.status]}</button>`:`<button data-detail="${c.id}">看看這份偏愛 ↗</button>`}</div></article>`}
function shop(){const list=shopMode==='wallet'?state.wallet.map(w=>({c:coupons[w.coupon],w})):coupons.map(c=>({c}));return pageHeading('THE LOVE COUPON SHOP','把偏愛，放進口袋。','16 種小小幸福，每一張都是「我想對你好」的另一種說法。')+`<div class="row between"><div class="tabs"><button data-shop="catalog" class="${shopMode==='catalog'?'selected':''}">兌換券商店 · 16</button><button data-shop="wallet" class="${shopMode==='wallet'?'selected':''}">我的票夾 · ${state.wallet.length}</button></div><button class="text-link" data-page="draw">每週免費抽一張 ↗</button></div><div class="tabs">${['全部','美味補給','親密時光','一起生活','貼心照顧'].map(t=>`<button data-filter="${t}" class="${filter===t?'selected':''}">${t}</button>`).join('')}</div><div class="grid">${list.filter(x=>filter==='全部'||x.c.category===filter).map(x=>ticket(x.c,x.w)).join('')||'<p class="empty full">這個分類還沒有券，去抽一份驚喜吧。</p>'}</div><div class="banner">♡ 商店供瀏覽券種；可用券由每週抽獎或男友後台贈送。兌換時間與內容一起商量，親密互動隨時可以改期或婉拒。</div>`}
function draw(){const used=state.draws.some(d=>d.week===weekInfo().key);return pageHeading('A WEEKLY LITTLE SURPRISE','這週的幸運，會是什麼呢？','轉一下，把一整週的小期待，變成一張只屬於你的戀愛券。')+`<section class="draw-panel"><span class="tag">每週一 00:00 更新 · 台北時間</span><div class="machine" id="machine"><div class="globe">${'<span></span>'.repeat(6)}</div><div class="machine-base"><b>♡</b></div></div><h2>${used?'這週的偏愛已經送達！':'今天的驚喜，等你打開'}</h2><p>16 種兌換券等機率抽取，每次一定獲得 1 張。</p><button id="drawButton" class="primary" ${used||busy?'disabled':''}>${busy?'正在打開小幸運…':used?'本週已抽取 ♡':'轉出我的小幸運 ✨'}</button><p style="margin:20px 0 0">距離下一次補給</p><div class="countdown" id="countdown"></div><span class="small">抽中的券會自動放進「我的票夾」</span></section><div class="banner">展示抽獎：限制僅存在此瀏覽器，可被清除資料或更換裝置繞過。已預留後端接口；正式上線須由伺服器驗證身分與每週唯一抽取紀錄。</div><div class="section-head"><h2>我的幸運紀錄</h2></div>${state.draws.length?state.draws.slice().reverse().map(d=>`<div class="card row between"><span>${coupons[d.coupon].icon} ${coupons[d.coupon].name}</span><span class="small">${esc(d.date)}</span></div>`).join(''):'<div class="card empty">第一份小幸運，還在等你 ♡</div>'}`}
function letters(){return pageHeading('LOVE, IN LITTLE WORDS','悄悄話，有一整封。','把不好意思當面說的喜歡，慢慢寫給彼此。')+`<div class="two"><form id="letterForm" class="card form"><h3>寫一封情書 ✉</h3><label>寄件人<select name="from"><option>帥氣可愛小寶貝男友</option><option>寶貝女友</option></select></label><label>信封上的話<input name="title" required maxlength="60" placeholder="今天又多喜歡你一點"></label><label>想說的話<textarea name="body" required maxlength="3000" placeholder="親愛的，我想告訴你…"></textarea></label><button class="primary">放進情書盒 ♡</button><span class="small">本機保存，不會真的寄出通知。</span></form><div class="stack">${state.letters.slice().reverse().map(l=>`<button class="note" style="text-align:left" data-letter="${l.id}"><span class="eyebrow">${l.sample?'SAMPLE LETTER':'JUST BETWEEN US'}</span><h3 style="margin-top:15px">${esc(l.title)}</h3><p>${esc(l.body.length>65?l.body.slice(0,65)+'…':l.body)}</p><div class="small" style="margin-top:15px">${esc(l.from)} · ${esc(l.date)}<br>輕輕拆開 ↗</div></button>`).join('')}</div></div>`}
function wishes(){return pageHeading('MAKE A LITTLE WISH','你的願望，我想聽。','想去的地方、想吃的東西，或一個想被理解的小心情。')+`<div class="two"><form id="wishForm" class="card form"><h3>投下一顆願望星星 ✧</h3><label>願望類別<select name="category"><option>一起去旅行</option><option>一起吃好吃的</option><option>想收到的小驚喜</option><option>想對你說</option></select></label><label>我的小願望<textarea name="body" required maxlength="500" placeholder="想和你去海邊，看一次日落。"></textarea></label><button class="primary">讓願望漂向你 ✨</button></form><div class="stack">${state.wishes.length?state.wishes.slice().reverse().map(w=>`<article class="card entry"><span class="tag">${esc(w.status)}</span><p style="margin-top:12px">${esc(w.body)}</p>${w.reply?`<div class="note">男友回覆：${esc(w.reply)}</div>`:''}<small>${esc(w.category)} · ${esc(w.date)}</small></article>`).join(''):'<div class="note"><h3>第一顆星星的位置，留給你。</h3><p>寫下願望後，能在男友後台回覆與更新進度。</p></div>'}</div></div>`}
function mood(){return pageHeading('EVERY FEELING IS WELCOME','今天的你，是什麼天氣？','晴天想陪你笑，下雨的時候，就陪你一起撐傘。')+`<div class="two"><form id="moodForm" class="card form"><h3>留一個心情給今天</h3><div class="moods">${[['🥰','開心'],['🙂','平靜'],['🥺','低落'],['😴','疲累'],['😤','煩躁']].map(([e,t])=>`<button type="button" data-mood="${t}" class="${moodSelected===t?'selected':''}">${e}<small>${t}</small></button>`).join('')}</div><label>想被怎麼陪伴？<select name="need"><option>給我一個抱抱</option><option>聽我說就好</option><option>陪我吃點好吃的</option><option>讓我安靜一下</option></select></label><label>多說一點點（選填）<textarea name="body" maxlength="500" placeholder="今天發生了…"></textarea></label><button class="primary">收藏今天的心情</button></form><div class="stack">${state.moods.length?state.moods.slice().reverse().map(m=>`<div class="card entry"><span class="tag">${esc(m.mood)}</span><h3 style="margin-top:12px">${esc(m.need)}</h3><p>${esc(m.body)||'今天先不說話，也沒關係。'}</p><small>${esc(m.date)}</small></div>`).join(''):'<div class="note"><h3>每一種心情，都值得被接住。</h3><p>不必把心情整理得很漂亮，才來這裡。</p></div>'}</div></div>`}
function memories(){return pageHeading('OUR SCRAPBOOK','把我們，收藏起來。','平凡的一天，因為有你，就值得被記住。')+`<form id="memoryForm" class="card form"><div class="two"><label>這個瞬間的名字<input name="title" required maxlength="60" placeholder="第一次一起做甜點"></label><label>是哪一天？<input name="day" type="date" required></label></div><label>當時的小故事<textarea name="body" required maxlength="1000" placeholder="那天的蛋糕有點歪，但我們笑得很開心。"></textarea></label><label>貼一張照片（選填，JPG / PNG / WebP，最多 1 MB）<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><button class="primary">貼進我們的剪貼簿 ♡</button></form><div class="section-head"><h2>我們的時光小格子</h2><span class="small">${state.memories.length} 個瞬間</span></div><div class="grid">${state.memories.length?state.memories.slice().reverse().map(m=>`<article class="card entry">${m.photo?`<img class="memory-img" src="${esc(m.photo)}" alt="${esc(m.title)}">`:'<div class="memory-placeholder">🌷</div>'}<span class="small">${esc(m.day)}</span><h3 style="margin-top:10px">${esc(m.title)}</h3><p>${esc(m.body)}</p></article>`).join(''):'<div class="note full"><h3>還沒貼上照片的空白，也很可愛。</h3><p>從今天開始，一起把這裡填滿吧。</p></div>'}</div>`}
const questions={'真心話':['你最近一次覺得被我愛著，是什麼時候？','如果重來一次第一次約會，你想帶我去哪裡？','有什麼小事是你一直想和我一起做的？','哪一個屬於我們的瞬間，你想再過一次？','你喜歡我怎麼安慰你？'],'甜蜜任務':['看著對方，說出今天最想感謝的一件事。','各挑一首歌，交換今天的心情。','如果彼此願意，牽手安靜待一分鐘。','用三個詞形容對方，告訴對方原因。','一起安排一個不用花錢的小約會。'],'默契二選一':['海邊日落，還是山上日出？','在家煮飯，還是出門探店？','驚喜約會，還是一起規劃？','下雨天看電影，還是窩著聊天？','收到一封情書，還是一束花？']};
function games(){return pageHeading('PLAY A LITTLE, LOVE A LOT','今天，重新認識你。','不用分輸贏的小遊戲，只要多靠近彼此一點。')+`<div class="tabs">${Object.keys(questions).map(t=>`<button data-game="${t}" class="${gameType===t?'selected':''}">${t}</button>`).join('')}</div><div class="card game-card"><span class="eyebrow">JUST THE TWO OF US</span><div style="font-size:45px;margin-top:18px">${gameType==='甜蜜任務'?'🎀':gameType==='真心話'?'💌':'🧩'}</div><div id="question" class="game-question">${questions[gameType][0]}</div><button id="nextQuestion" class="primary">換一張小卡 ↻</button><p style="margin:20px 0 0">輪流回答，或先猜猜對方的答案。<br>不想回答或不想做，隨時都可以跳過。</p></div>`}
function admin(){const pending=state.wallet.filter(w=>w.status==='pending');return pageHeading('FROM YOUR PERSONAL LOVE MANAGER','專屬寵愛，補貨中。','管理小驚喜、回應願望，把「我會記得」變成真的。')+`<div class="banner">展示後台 · 未接入登入與角色權限，任何使用此瀏覽器的人都可操作。資料只在本機，不會通知另一半。</div><div class="grid stats"><div class="card"><b>${pending.length}</b><span class="small">等待兌換</span></div><div class="card"><b>${state.wishes.filter(w=>w.status!=='已實現').length}</b><span class="small">等待實現的願望</span></div><div class="card"><b>${state.wallet.filter(w=>w.status==='done').length}</b><span class="small">已完成的小幸福</span></div></div><div class="two"><form id="settingsForm" class="card form"><h3>我們的小設定</h3><label>專屬暱稱<input name="name" value="${esc(state.settings.name)}" required maxlength="20"></label><label>在一起的日子<input type="date" name="anniversary" value="${esc(state.settings.anniversary)}"></label><button>儲存設定</button></form><form id="giftForm" class="card form"><h3>偷偷送一張券 🎟️</h3><label>挑選一份偏愛<select name="coupon">${coupons.map(c=>`<option value="${c.id}">${c.icon} ${c.name}</option>`).join('')}</select></label><p>會直接加入本機的「我的票夾」，可以立刻試用兌換流程。</p><button class="primary">送進寶貝的票夾</button></form></div><div class="section-head"><h2>兌換小清單</h2></div><div class="card">${pending.length?pending.map(w=>`<div class="table-row"><div class="row between"><h3>${coupons[w.coupon].icon} ${coupons[w.coupon].name}</h3><button data-complete="${w.id}">標記已完成 ♡</button></div><p>${esc(w.note)||'沒有附上備註，找時間一起聊聊吧。'}</p><span class="small">${esc(w.requestedAt)}</span></div>`).join(''):'<p style="margin:0">目前沒有等待兌換的券。</p>'}</div><div class="section-head"><h2>願望回音</h2></div><div class="stack">${state.wishes.map(w=>`<form class="card form wishReply" data-id="${w.id}"><p>${esc(w.body)}</p><label>回覆<input name="reply" value="${esc(w.reply||'')}" required maxlength="300"></label><label>進度<select name="status">${['已收到','安排中','已實現'].map(s=>`<option ${w.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button>儲存回音</button></form>`).join('')||'<div class="card small">許願池有新願望時，就會出現在這裡。</div>'}</div>`}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}
function close(){ $('#modal').close() }
$('#modal').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()});
function updateCountdown(){const el=$('#countdown');if(!el)return;const sec=Math.max(0,Math.floor((weekInfo().next-Date.now())/1000));el.textContent=`${Math.floor(sec/86400)} 天 ${String(Math.floor(sec/3600)%24).padStart(2,'0')} : ${String(Math.floor(sec/60)%60).padStart(2,'0')} : ${String(sec%60).padStart(2,'0')}`;if(!busy&&$('#drawButton'))$('#drawButton').disabled=state.draws.some(d=>d.week===weekInfo().key)}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-page]');if(!el)return;const d=el.dataset;if(d.page){if(d.page==='shop'&&el.classList.contains('wallet'))shopMode='wallet';location.hash=d.page;if(page===d.page)render()}if(d.shop){shopMode=d.shop;render()}if(d.filter){filter=d.filter;render()}if(d.close!==undefined)close();if(d.detail!==undefined){const c=coupons[+d.detail];modal(`<div class="prize">${c.icon}</div><h2>${c.name}</h2><p>${c.desc}</p><p class="small">一次兌換一份體驗；內容、預算與時間由兩人確認。<br>不設展示到期日，親密互動須彼此願意。</p><div class="row"><button data-close>先收藏在心裡</button><button class="primary" id="goDraw">去抽一張券</button></div>`)}if(el.id==='goDraw'){close();location.hash='draw'}if(d.redeem){const w=state.wallet.find(w=>w.id===d.redeem);if(!w||w.status!=='available')return;modal(`<h2>兌現 ${coupons[w.coupon].name}</h2><p>留個時間或小心願，等男友回應。</p><form id="redeemForm" data-id="${w.id}" class="form"><label>兌換備註（選填）<textarea name="note" maxlength="300" placeholder="週六下午，一起吃草莓蛋糕好嗎？"></textarea></label><button class="primary">送出模擬申請 ♡</button><button type="button" data-close>再想一下</button></form>`)}if(d.letter){const l=state.letters.find(l=>l.id===d.letter);modal(`<div class="prize">💌</div><h2>${esc(l.title)}</h2><p style="text-align:left">${esc(l.body)}</p><p class="small">${esc(l.from)} · ${esc(l.date)}</p><button data-close class="primary">好好收進心裡 ♡</button>`)}if(d.mood){moodSelected=d.mood;document.querySelectorAll('[data-mood]').forEach(b=>b.classList.toggle('selected',b.dataset.mood===moodSelected))}if(d.game){gameType=d.game;render()}if(el.id==='nextQuestion'){const arr=questions[gameType].filter(q=>q!==$('#question').textContent);$('#question').textContent=arr[Math.floor(Math.random()*arr.length)]}if(d.complete){const w=state.wallet.find(w=>w.id===d.complete);if(w?.status==='pending'){w.status='done';save();render();toast('已記下這份完成的小幸福 ♡')}}if(el.id==='drawButton'&&!busy){busy=true;el.disabled=true;el.textContent='正在打開小幸運…';$('#machine')?.classList.add('shaking');try{const result=await window.loveApi.drawWeekly();await new Promise(r=>setTimeout(r,1500));const c=coupons[result.couponId];if($('#modal').open)close();modal(`<span class="eyebrow">LUCKY YOU!</span><div class="prize">${c.icon}</div><h2>抽中了，${c.name}！</h2><p>${c.desc}<br>已放進你的票夾，隨時可以兌現。</p><button id="seeWallet" class="primary">看看我的幸運券 ♡</button>`);for(let i=0;i<24;i++){const p=document.createElement('span');p.className='confetti';p.textContent=['♡','✧','✿'][i%3];p.style.cssText=`left:${Math.random()*100}%;color:${['#c87584','#ddbb79','#b3b58b'][i%3]};animation-delay:${Math.random()*.5}s`;document.body.appendChild(p);setTimeout(()=>p.remove(),3200)}}catch(err){toast(err.message)}finally{busy=false;render()}}if(el.id==='installApp'&&installEvt){const ev=installEvt;installEvt=null;ev.prompt();const r=await ev.userChoice;render();if(r.outcome==='accepted')toast('補給站已放到桌面囉 ♡')}if(el.id==='seeWallet'){close();shopMode='wallet';filter='全部';location.hash='shop'}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));if(Object.entries(data).some(([k,v])=>typeof v==='string'&&f.elements[k]?.required&&!v.trim())){toast('請填入文字，不能只有空白喔。');return}if(f.id==='letterForm')state.letters.push({id:uid(),...data,date:date()});else if(f.id==='wishForm')state.wishes.push({id:uid(),...data,status:'已收到',date:date()});else if(f.id==='moodForm')state.moods.push({id:uid(),...data,mood:moodSelected,date:date()});else if(f.id==='settingsForm'){if(data.anniversary&&new Date(data.anniversary+'T00:00:00+08:00')>Date.now()){toast('紀念日不能設定在未來喔。');return}state.settings=data}else if(f.id==='giftForm')state.wallet.push({id:uid(),coupon:+data.coupon,status:'available',source:'男友的小驚喜'});else if(f.id==='redeemForm'){const w=state.wallet.find(w=>w.id===f.dataset.id);if(!w||w.status!=='available')return;w.status='pending';w.note=data.note;w.requestedAt=date();close()}else if(f.classList.contains('wishReply'))Object.assign(state.wishes.find(w=>w.id===f.dataset.id),data);else if(f.id==='memoryForm'){const file=f.elements.photo.files[0];if(file&&(file.size>1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))){toast('請選擇 1 MB 以內的 JPG、PNG 或 WebP 照片。');return}let photo='';if(file){try{photo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}catch{toast('照片讀取失敗，請重試。');return}}const item={id:uid(),title:data.title,day:data.day,body:data.body,photo};state.memories.push(item);if(!save()){state.memories.pop();return}render();toast('這個瞬間已收藏在本機 ♡');return}else return;if(save()){render();toast('已保存在本機，心意收到 ♡')}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'smooth'})});window.addEventListener('storage',e=>{if(e.key===KEY){try{state=JSON.parse(e.newValue)||initial();render(true)}catch{}}});setInterval(updateCountdown,1000);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvt=e;if(page==='home')render(true)});window.addEventListener('appinstalled',()=>{installEvt=null;if(page==='home')render(true)});if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});save();render();

